// Fold every probe into ONE verdict, so one Healthchecks check covers N
// subjects (the box-report-ran argument: 1 check, 17 things). The reason text
// travels into the alert, so a red says WHAT broke without an SSH session.
//
// A probe that cannot answer at all must read as a problem, never as a pass —
// `neverError` turns non-2xx into data, and `onError: continueRegularOutput`
// turns a timeout, a DNS failure or a refused login into an item with no
// result. Both land here as problems rather than as silence.
//
// THRESHOLDS LIVE HERE, NOT IN SQL. monitoring.health returns raw counts and
// ages on purpose: retuning a number in a view means running DDL against the
// pilot database, which is expensive enough that nobody does it, and a monitor
// nobody retunes gets muted instead. Every limit below is one edit away.
const problems = [];
const notes = [];

const mins = (s) => Math.round(s / 60) + 'm';
const hours = (s) => (s / 3600).toFixed(1) + 'h';

// ── probe 1: the web service ────────────────────────────────────────────────
// /health is unauthenticated and routed BEFORE the auth check and the IP
// allowlist, on purpose: a health check that only answers while everything else
// is healthy is not a health check. So the status code doubles as a build
// fingerprint:
//   200 -> current branch is deployed; body carries {commit, checks.db}, and
//          the probe has silently upgraded from "is it up" to "is it working".
//   401 -> alive, but the deployed commit PREDATES /health, so auth answered
//          first. Liveness only. Not an incident — it is the known commit drift.
//   503 -> /health ran and the DB round-trip failed. Real incident.
let web = null;
try {
  web = $('Probe web /health').first().json;
} catch (err) {
  web = null;
}
const code = web && typeof web.statusCode === 'number' ? web.statusCode : null;
if (code === null) {
  const why = (web && (web.error || web.message)) || 'no response';
  problems.push('web: unreachable (' + String(why).slice(0, 120) + ')');
} else if (code === 200) {
  const body = (web && web.body) || {};
  const db = (body.checks && body.checks.db) || 'unknown';
  const commit = String(body.commit || 'unknown').slice(0, 7);
  if (db !== 'ok') {
    problems.push('web: /health says db=' + db + ' (commit ' + commit + ')');
  } else {
    notes.push('web 200 db=ok commit=' + commit);
  }
} else if (code === 401) {
  notes.push('web 401 (alive; deploy predates /health)');
} else {
  problems.push('web: HTTP ' + code);
}

// ── probe 2: the workers, via monitoring.health ─────────────────────────────
// This is the only probe that can answer "is it DOING its job". From outside a
// worker, "zero rows processed because none arrived" and "zero rows processed
// because it is wedged" are the same observation; only our own data separates
// them.
let row = null;
try {
  row = $('Query pilot DB').first().json;
} catch (err) {
  row = null;
}

if (!row || row.observed_at === undefined) {
  const why = (row && (row.error || row.message)) || 'no row returned';
  problems.push('db: monitoring.health unreadable (' + String(why).slice(0, 140) + ')');
} else {
  // NULL means the relevant set is EMPTY (no pending calls, no captures yet) —
  // "nothing to say", never zero. Comparing null numerically would silently read
  // as 0 and turn every quiet period into a pass on a check that never ran.
  const num = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
  const over = (v, limit, msg) => {
    const n = num(v);
    if (n !== null && Number.isFinite(n) && n > limit) problems.push(msg(n));
  };

  // Calls-worker stalled: something is waiting and nothing is taking it.
  over(row.calls_pending_oldest_s, 900, (n) => 'calls-worker stalled: oldest pending ' + mins(n));

  // The strongest wedge evidence there is — a worker CLAIMED this row and never
  // finished, so it cannot be explained away by an empty inbox. Given a wide
  // grace because transcription legitimately takes minutes.
  over(row.calls_processing_oldest_s, 1800, (n) => 'calls-worker wedged: a row has been processing ' + mins(n));

  over(row.calls_error_1h, 3, (n) => 'call pipeline erroring: ' + n + ' in the last hour');
  over(row.calls_max_attempts, 4, (n) => 'retry storm: a call is on attempt ' + n);

  // Any non-zero value is a retention-promise breach, so there is no threshold
  // to tune: audio past its delete date, not deleted, not on legal hold.
  over(row.calls_purge_backlog, 0, (n) => 'Calls-purge stopped: ' + n + ' recording(s) past their delete date');

  // lifecycle-heart runs */5 but the heavy sweeps self-gate to quarter-hour
  // ticks, so the rollup is ~15 min old in normal operation. One hour is four
  // missed ticks — a stopped cron, not a slow one.
  over(row.cost_rollup_age_s, 3600, (n) => 'lifecycle-heart stale: cost rollup ' + mins(n) + ' old');

  over(row.nudges_queued_oldest_s, 3600, (n) => 'nudge delivery stalled: oldest queued ' + mins(n));

  // The escalation sweep hands a nudge to the manager after 48h by default. 72h
  // means the deadline passed a full day ago and nothing moved. Deliberately not
  // mirroring NUDGE_ESCALATE_HOURS — a monitor that tracks a code constant
  // breaks quietly when the constant changes.
  over(row.nudges_asked_oldest_s, 259200, (n) => 'nudge escalation stalled: oldest asked ' + hours(n));

  // Wide on purpose. This is a small pilot; 24h of silence was the FIRST reading
  // we ever took, so a tight limit would have paged on day one, and a monitor
  // that cries wolf immediately gets muted. Tighten once we have a week of
  // baseline.
  over(row.l1_capture_age_s, 172800, (n) => 'no L1 capture in ' + hours(n));

  const pend = num(row.calls_pending);
  const proc = num(row.calls_processing);
  notes.push('db ok (calls ' + (pend === null ? 0 : pend) + 'p/' + (proc === null ? 0 : proc) + 'r)');
}

const ok = problems.length === 0;
return [{ json: { ok: ok, detail: ok ? notes.join('; ') : problems.join('; ') } }];
